// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- API Base URL from env ---
const apiBaseUrl = process.env.RORAH_API_URL || 'http://localhost:3031';

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Validation items ---
if (!body.items || !Array.isArray(body.items) || body.items.length === 0) {
  return {
    error: true,
    error_code: 'MISSING_ITEMS',
    message: 'Le champ "items" est requis et doit etre un tableau non vide'
  };
}

// --- Validation de chaque item ---
const validatedItems = [];
for (let i = 0; i < body.items.length; i++) {
  const item = body.items[i];

  if (!item.product_snapshot || !item.product_snapshot.name) {
    return {
      error: true,
      error_code: 'INVALID_ITEM',
      message: `Item ${i}: product_snapshot.name est requis`
    };
  }

  if (typeof item.product_snapshot.price_cents !== 'number') {
    return {
      error: true,
      error_code: 'INVALID_ITEM',
      message: `Item ${i}: product_snapshot.price_cents est requis`
    };
  }

  const quantity = item.quantity || 1;
  if (quantity < 1 || quantity > 99) {
    return {
      error: true,
      error_code: 'INVALID_QUANTITY',
      message: `Item ${i}: quantity doit etre entre 1 et 99`
    };
  }

  validatedItems.push({
    product_id: item.product_id || null,
    product_snapshot: {
      name: item.product_snapshot.name,
      description: item.product_snapshot.description || null,
      price_cents: item.product_snapshot.price_cents,
      currency: item.product_snapshot.currency || 'EUR',
      image_url: item.product_snapshot.image_url || null,
      brand: item.product_snapshot.brand || null,
      seller: item.product_snapshot.seller || null
    },
    quantity: quantity
  });
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    items: validatedItems,
    project_id: projectId,
    api_base_url: apiBaseUrl
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'API_ERROR',
      message: apiResponse.error?.message || 'Erreur API',
      http_status: apiResponse.error?.http_status || 500
    }
  };
}

return {
  success: true,
  added_count: validationData.data.items.length,
  cart: {
    total_cents: apiResponse.cart?.total_cents || apiResponse.total_cents || 0,
    item_count: apiResponse.cart?.item_count || apiResponse.item_count || 0
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};
